package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// extractUserID gets user from X-User-ID header (set by upstream auth proxy)
func extractUserID(r *http.Request) string {
	return r.Header.Get("X-User-ID")
}

// searchDocuments allows full-text search with optional filters
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := extractUserID(r)
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	query := r.URL.Query().Get("q")
	classFilter := r.URL.Query().Get("class")
	sortBy := r.URL.Query().Get("sort")

	// Build base query with parameterized user filter
	baseQuery := "SELECT id, title, content, owner_id, classification FROM documents WHERE owner_id = $1"

	// Add text search if provided
	if query != "" {
		// Using PostgreSQL full-text search - parameterized
		baseQuery += " AND to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $2)"
	}

	// Classification filter - validated against enum
	allowedClasses := map[string]bool{"public": true, "internal": true, "confidential": true, "restricted": true}
	if classFilter != "" && allowedClasses[strings.ToLower(classFilter)] {
		baseQuery += fmt.Sprintf(" AND classification = '%s'", strings.ToLower(classFilter))
	}

	// Sort - THIS IS THE VULNERABILITY: unsanitized ORDER BY
	if sortBy != "" {
		// Developer assumed sort would only be column names
		baseQuery += " ORDER BY " + sortBy
	} else {
		baseQuery += " ORDER BY id DESC"
	}

	baseQuery += " LIMIT 50"

	var rows *sql.Rows
	var err error
	if query != "" {
		rows, err = db.Query(baseQuery, userID, query)
	} else {
		rows, err = db.Query(baseQuery, userID)
	}
	if err != nil {
		log.Printf("Query error for user %s: %v", userID, err)
		http.Error(w, "search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// getDocument retrieves a single document - uses parameterized query
func getDocument(w http.ResponseWriter, r *http.Request) {
	userID := extractUserID(r)
	docID := r.URL.Query().Get("id")

	var d Document
	err := db.QueryRow(
		"SELECT id, title, content, owner_id, classification FROM documents WHERE id = $1 AND owner_id = $2",
		docID, userID,
	).Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(d)
}

func main() {
	http.HandleFunc("/api/documents/search", searchDocuments)
	http.HandleFunc("/api/documents/get", getDocument)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
